WHERE o.deleted = 0
AND (o.code LIKE #{f.keyword} OR o.name LIKE #{f.keyword} OR o.short_name LIKE #{f.keyword})
AND o.unit_type = #{f.unitType}
AND o.region_code = #{f.regionCode}
AND o.parent_id = #{f.parentId}

mapper.select:
SELECT  FROM org_unit o LEFT JOIN org_unit p ON p.id = o.parent_id

ORDER BY ${q.orderBy}
LIMIT #{q.size} OFFSET #{q.offset}
